import os
import torch


class Config:
    # -------------------------------------------------------------------------
    # Reproducibility
    # -------------------------------------------------------------------------
    SEED = 42

    # -------------------------------------------------------------------------
    # Paths and Directories
    # -------------------------------------------------------------------------
    INPUT_DIR = "./input"
    METADATA_DIR = "./metadata"

    # Metadata files generated by the analysis script
    TRAIN_METADATA_PATH = os.path.join(METADATA_DIR, "train_metadata.csv")
    VAL_METADATA_PATH = os.path.join(METADATA_DIR, "val_metadata.csv")
    TEST_METADATA_PATH = os.path.join(METADATA_DIR, "test_metadata.csv")
    SAMPLE_SUBMISSION_PATH = os.path.join(INPUT_DIR, "sample_submission.csv")

    # Output directories
    # Using 'idea_24' as the specific experiment identifier
    WORKING_DIR = "./working/idea_24"
    CACHE_DIR = os.path.join(WORKING_DIR, "cache")
    CHECKPOINT_DIR = os.path.join(WORKING_DIR, "checkpoints")
    SUBMISSION_DIR = "./submission"

    # Ensure output directories exist
    os.makedirs(CACHE_DIR, exist_ok=True)
    os.makedirs(CHECKPOINT_DIR, exist_ok=True)
    os.makedirs(SUBMISSION_DIR, exist_ok=True)

    # File paths for caching processed graphs (using numpy format for speed/compatibility)
    TRAIN_GRAPHS_CACHE = os.path.join(CACHE_DIR, "train_graphs.npz")
    VAL_GRAPHS_CACHE = os.path.join(CACHE_DIR, "val_graphs.npz")
    TEST_GRAPHS_CACHE = os.path.join(CACHE_DIR, "test_graphs.npz")
    TARGET_SCALER_CACHE = os.path.join(CACHE_DIR, "target_scaler.npz")

    # Checkpoint and Submission paths
    BEST_MODEL_PATH = os.path.join(CHECKPOINT_DIR, "best_model.pth")
    SUBMISSION_PATH = os.path.join(SUBMISSION_DIR, "submission.csv")

    # -------------------------------------------------------------------------
    # Data / Graph Construction Hyperparameters
    # -------------------------------------------------------------------------
    CUTOFF = 5.0  # Neighbor search cutoff radius in Angstroms
    MAX_NEIGHBORS = 50  # Maximum number of neighbors per node to consider

    # Debugging: Set to a small integer (e.g., 100) to limit dataset size for fast testing.
    # Set to None for full training.
    DEBUG_SAMPLE_SIZE = None

    # -------------------------------------------------------------------------
    # Model Architecture Hyperparameters
    # -------------------------------------------------------------------------
    ATOM_EMBEDDING_DIM = 64
    HIDDEN_DIM = 64
    RBF_BINS = 60  # Number of Gaussian RBF basis functions for edge expansion
    RBF_GAMMA = 10.0  # Gamma parameter for RBF (controls width)
    NUM_LAYERS = 4  # Number of receiver-aware interaction blocks
    DROPOUT = 0.1  # Dropout rate applied in blocks and heads
    MAX_ATOMIC_NUM = 100  # Size of embedding dictionary (In is 49, so 100 is safe)

    # -------------------------------------------------------------------------
    # Training Hyperparameters
    # -------------------------------------------------------------------------
    BATCH_SIZE = 48
    LEARNING_RATE = 1e-3
    WEIGHT_DECAY = 1e-4
    EPOCHS = 150
    PATIENCE = 20  # Early stopping patience

    # -------------------------------------------------------------------------
    # Compute
    # -------------------------------------------------------------------------
    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"
    NUM_WORKERS = 4  # Number of dataloader workers

    # -------------------------------------------------------------------------
    # Target Variables
    # -------------------------------------------------------------------------
    TARGET_COLS = ["formation_energy_ev_natom", "bandgap_energy_ev"]
